    public static View build(Activity a, AlfaUiNavigation.Screen s, RuntimeSessionManager m, Runnable appearanceAction, Runnable refreshAction) {
        switch (s) {
            case NETWORK: return network(a);
            case SECURITY: return security(a);
            case STORAGE: return storage(a);
            case AUDIT: return audit(a);
            case PROJECT: return project(a);
            case SESSIONS: return sessions(a, m);
            case SPLIT: return split(a, m);
            case FLOATING: return floating(a);
            case APPEARANCE: return appearance(a, appearanceAction);
            case SETTINGS: return settings(a, refreshAction, appearanceAction);
            case DIAGNOSTICS: return diagnostics(a, m);
            default: return evidence(a, s.name(), "Canonical terminal/runtime surface handles this state.");
        }
    }

