    private static void tree(StringBuilder out,File dir,String prefix,int depth,int max){if(depth<0||max<=0)return;File[] fs=dir.listFiles();if(fs==null){out.append(prefix).append("<unreadable>\n");return;}List<File> l=new ArrayList<>();Collections.addAll(l,fs);Collections.sort(l,(x,y)->x.getName().compareToIgnoreCase(y.getName()));int n=0;for(File f:l){if(n++>=max){out.append(prefix).append("… truncated\n");break;}out.append(prefix).append(f.getName()).append(f.isDirectory()?"/":"").append('\n');if(f.isDirectory())tree(out,f,prefix+"  ",depth-1,max);}}
